#!/usr/bin/env python3
"""Render the control map as the kernel and userspace C tables.

Usage:
    tools/vendor/render-controls.py tools/vendor/control-map-zg01.json \
        src/zg01_controls_generated.h tools/zg01_controls_generated.h

The control map is the single source of truth.  The kernel table holds the
writable rows that are not already in the driver's manual zg01_param_ctls[]
table; the userspace table holds every address, including the read-only
exclusions, so zgctl can report them.  The committed headers are checked
against a fresh render by tests/test-generated-controls.sh.
"""
import argparse
import json

CONV = {
    'id': 'CONV_ID',
    'gain': 'CONV_GAIN',
    'freq': 'CONV_FREQ',
    'q': 'CONV_Q',
}

TYPE = {
    'boolean': 'SNDRV_CTL_ELEM_TYPE_BOOLEAN',
    'integer': 'SNDRV_CTL_ELEM_TYPE_INTEGER',
}

FLAG = {
    'raw': 'ZG01_CTL_RAW',
    'read-only': 'ZG01_CTL_READONLY',
}


def c_string(value):
    """A C string literal for a control name."""
    return '"' + value.replace('\\', '\\\\').replace('"', '\\"') + '"'


def load_map(path):
    with open(path) as handle:
        rows = json.load(handle)
    addresses = set()
    for row in rows:
        address = row['address']
        if address in addresses:
            raise SystemExit(f'duplicate address {address}')
        addresses.add(address)
        if row['type'] not in TYPE:
            raise SystemExit(f'{row["control_name"]}: unknown type {row["type"]}')
        if row['conv'] not in CONV:
            raise SystemExit(f'{row["control_name"]}: unknown conv {row["conv"]}')
        if row['provenance'] not in ('existing', 'vendor-model', 'raw',
                                     'read-only'):
            raise SystemExit(
                f'{row["control_name"]}: unknown provenance '
                f'{row["provenance"]}')
    return sorted(rows, key=lambda row: row['address'])


def kernel_rows(rows):
    """Writable parameters that the manual control table does not already name."""
    return [row for row in rows
            if row['writable'] and row['provenance'] != 'existing']


def render_kernel(rows):
    extras = kernel_rows(rows)
    if not extras:
        raise SystemExit('control map has no generated kernel controls')

    lines = [
        '/*',
        ' * Generated by tools/vendor/render-controls.py from',
        ' * tools/vendor/control-map-zg01.json.  Do not edit by hand.',
        ' *',
        ' * The writable parameters that are not already in zg01_param_ctls[].',
        ' * Read-only status parameters are intentionally absent: they must not',
        ' * become ALSA controls.',
        ' */',
        '#ifndef ZG01_CONTROLS_GENERATED_H',
        '#define ZG01_CONTROLS_GENERATED_H',
        '',
        '#define ZG01_EXTRA_PARAM_MAX_ADDR '
        f'{max(row["address"] for row in extras)}',
        '',
        'static const struct zg01_param_ctl zg01_extra_param_ctls[] = {',
    ]
    for row in extras:
        lines.append(
            f'    {{ {c_string(row["control_name"])}, {row["address"]}, '
            f'{TYPE[row["type"]]}, {row["min"]}, {row["max"]}, '
            f'{CONV[row["conv"]]}, {row["def"]} }},')
    lines += [
        '};',
        '',
        '#endif /* ZG01_CONTROLS_GENERATED_H */',
        '',
    ]
    return '\n'.join(lines)


def render_userspace(rows):
    lines = [
        '/*',
        ' * Generated by tools/vendor/render-controls.py from',
        ' * tools/vendor/control-map-zg01.json.  Do not edit by hand.',
        ' *',
        ' * Every addressable parameter, including the read-only status rows.',
        ' * A writable row with provenance "raw" carries ZG01_CTL_RAW; a row that',
        ' * must not be written carries ZG01_CTL_READONLY.',
        ' */',
        '#ifndef ZG01_USER_CONTROLS_GENERATED_H',
        '#define ZG01_USER_CONTROLS_GENERATED_H',
        '',
        '/* Conversions, matching enum zg01_conv in src/zg01_control.c. */',
        '#ifndef ZG01_USER_CONV_DEFINED',
        '#define ZG01_USER_CONV_DEFINED',
        'enum {',
        '    CONV_ID,',
        '    CONV_GAIN,',
        '    CONV_FREQ,',
        '    CONV_Q,',
        '};',
        '#endif',
        '',
        'static const struct zg01_user_control zg01_user_controls[] = {',
    ]
    for row in rows:
        flags = FLAG.get(row['provenance'], '0')
        lines.append(
            f'    {{ {row["address"]}, {c_string(row["control_name"])}, '
            f'{row["min"]}, {row["max"]}, {CONV[row["conv"]]}, '
            f'{row["def"]}, {flags} }},')
    lines += [
        '};',
        '',
        '#endif /* ZG01_USER_CONTROLS_GENERATED_H */',
        '',
    ]
    return '\n'.join(lines)


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('map_json')
    ap.add_argument('kernel_header')
    ap.add_argument('userspace_header')
    args = ap.parse_args()

    rows = load_map(args.map_json)
    with open(args.kernel_header, 'w') as handle:
        handle.write(render_kernel(rows))
    with open(args.userspace_header, 'w') as handle:
        handle.write(render_userspace(rows))
    print(f'wrote {args.kernel_header}')
    print(f'wrote {args.userspace_header}')


if __name__ == '__main__':
    main()
